// 錯誤教案 #6：淺拷貝導致重複釋放（同一塊記憶體被還了兩次）
#include <iostream>

class Buffer {
public:
  explicit Buffer(int n) : data_(new int[n]), n_(n) {}   //@ @tts [step-in] 建立 Buffer 時，配一塊有 n 格的陣列，data_ 指向它
  ~Buffer() { delete[] data_; }          //@ @bug 解構子會 delete[] 自己的 data_。若兩個物件的 data_ 指向同一塊，這塊記憶體就會被釋放兩次 @tts [step-in] 解構子釋放 data_ 指向的那塊陣列
  int* data_;                            //@ @guide data_ 指向堆積上的一塊陣列 
  int n_;                                //@ @guide n_ 是陣列的格數 
};

int main() {                             //@ @tts [next] 程式開始
  Buffer a(3);                           //@ @tts [step-in] 建立 a，它配了一塊陣列，a.data_ 指向那塊
  a.data_[0] = 1;                        //@ @tts [next] 把 a 的第一格設為 1
  Buffer b = a;                          //@ @bug 這是淺拷貝：只複製了 data_ 的位址，沒有複製陣列的內容。a 和 b 現在指向同一塊記憶體 @tts [next] b 複製了 a 的位址，兩者指向同一塊陣列
  std::cout << "b.data_[0] = " << b.data_[0] << std::endl;  //@ @tts [next] 印出 b 的第一格，是 1
  return 0;                              //@ @tts [step-in] 離開 main，先解構 b，再解構 a
}  //@ @tts [continue] 教案播放完畢
